  void LiveTick(bool flushAll=false){
   bool details=flushAll||(DateTime.UtcNow-lastMetrics).TotalSeconds>=1;var metrics=activeMetrics;var p=metrics==null?latestProgress:metrics.Progress(details);
   if(p!=null){
