    L("RateLabel").ToolTip=p.Activity+(p.CopyPhase?" · "+(p.EffectiveBytesPerSecond/1000000.0).ToString("0.0")+" effective MB/s": " · "+p.WorkPerSecond.ToString("0.0")+" files/s");if(p.Stages!=null){SetRows("MetricsGrid",p.Stages);lastMetrics=DateTime.UtcNow;}
   }
