  void Import(bool retry=false){if(plan==null||repo==null)return;string solve=Convert.ToString(C("ImportSolveMode").SelectedItem),rotation=Convert.ToString(C("ImportRotationMode").SelectedItem);if(solve!="Off"&&!PlateSolve.Configured(settings)){Configure();if(!PlateSolve.Configured(settings)||plan==null||repo==null)return;}var importSelection=ImportWorkflow.Select(visibleImports,SkipFlagged,retry);if(importSelection.Count==0)return;var options=new ImportOptions{IgnoreFailed=settings.IgnoreFailed,DeleteOriginals=((CheckBox)Window.FindName("DeleteOriginalsCheck")).IsChecked==true,SourceRoot=plan.Source,Workers=settings.CopyWorkers,OnFrame=LiveFrame,ScanMetrics=plan.Metrics,DeferFinish=true};ImportResult result=null;BeginLive(false);
