  RotationResult AnalyzeGroup(List<Frame> g,CancellationToken ct,Action<int> counted=null){foreach(var f in g)repo.ValidateCapture(f,ct);string cacheKey="rotation180:"+Util.HashText(Util.Serialize(g.Select(f=>new{f.Hash,f.ImageKey,f.ImageIndex,f.Observed,f.ObservedUtc,f.RA,f.Dec,f.Calibration,f.Latitude,f.Longitude}).OrderBy(f=>f.Hash).ToList())+"|"+settings.Latitude+"|"+settings.Longitude);string cached=repo.CacheGet(cacheKey);var result=cached==null?Rotation.Analyze(repo,g,settings.Latitude,settings.Longitude,ct,Progress,counted):Util.Deserialize<RotationResult>(cached);result.Mount=MountLabels.Normalize(result.Mount);if(cached==null)repo.CachePut(cacheKey,Util.Serialize(result));result.Session=g[0].Session+"_"+Util.HashText(g[0].Group).Substring(0,8);repo.SaveRotation(result);string json=Util.Serialize(result);foreach(var f in g){f.RotationReport=json;if(!(f.MountEvidence??"").StartsWith("User")&&!(f.MountEvidence??"").StartsWith("Explicit")){f.Mount=result.Mount;f.MountEvidence=result.Evidence;}repo.Refile(f,ct);LiveFrame(f);}return result;}
  void AutoIdentify(List<Frame> frames,CancellationToken ct,PipelineMetrics metrics,bool everyFile){var groups=everyFile?frames.Select(f=>new List<Frame>{f}).ToList():frames.GroupBy(f=>f.MakeText+"|"+f.Session+"|"+f.Width+"x"+f.Height+"|"+f.Camera).Select(g=>g.ToList()).ToList();metrics.Phase(groups.Count,0,"Identifying targets");foreach(var items in groups){ct.ThrowIfCancellationRequested();Frame sample=items.FirstOrDefault(f=>f.Kind=="Stack")??items[items.Count/2];using(var stage=metrics.Begin("Target identification",sample.OriginalName)){try{
