  void Identify(bool imported){if(repo==null)return;var selected=Context(imported).Where(f=>f.Kind=="Light"||f.Kind=="Stack"||f.Kind=="Unknown").ToList();if(selected.Count==0){MessageBox.Show(Window,"Select a light exposure or telescope stack to identify.","Select a capture");return;}
   var named=selected.Where(f=>Catalog.TargetFromFilename(f.OriginalName)!=null).ToList();var unresolved=selected.Except(named).ToList();int identified=0;
   if(named.Count==0){IdentifyByPlate(imported,unresolved,0);return;}
   Run(ct=>{foreach(var original in named){ct.ThrowIfCancellationRequested();Frame updated=original.Clone();if(TargetIdentification.ApplyFilename(updated)){StoreIdentification(original,updated,imported,ct);identified++;}}return identified+" captures identified from filenames.";},message=>{if(imported)FilterImports();L("StatusLabel").Text=message;if(unresolved.Count>0)IdentifyByPlate(imported,unresolved,identified);});
