  void IdentifyByPlate(bool imported,List<Frame> selected,int named){
   if(!PlateSolve.Configured(settings)){Configure();if(!PlateSolve.Configured(settings)){L("StatusLabel").Text=named+" identified from filenames; "+selected.Count+" require a configured plate solver.";return;}}
   var groups=selected.GroupBy(f=>f.MakeText+"|"+f.Telescope+"|"+f.Session+"|"+f.Width+"x"+f.Height+"|"+f.Camera).Select(g=>g.ToList()).ToList();int index=0,solved=0,unresolved=0;Action next=null;
   next=()=>{if(closing)return;if(index>=groups.Count){L("StatusLabel").Text=named+" identified from filenames; "+solved+" plate solved; "+unresolved+" unresolved.";return;}var items=groups[index++];Frame sample=items.FirstOrDefault(f=>f.Kind=="Stack")??items.First();SolveResult solution=null;string failure=null;
    Run(ct=>{try{solution=PendingImport(sample,imported)?PlateSolve.Solve(sample,CapturePath(sample,imported),settings,ct,t=>Progress(new ProgressInfo{Stage="Target identification",Text=t})):repo.CachedSolve(sample,settings,ct,t=>Progress(new ProgressInfo{Stage="Target identification",Text=t}));}catch(OperationCanceledException){throw;}catch(Exception e){failure=e.Message;}return "";},message=>{
     if(failure!=null){unresolved+=items.Count;foreach(var item in items)item.Notes=(item.Notes??"")+"Plate solve unavailable: "+failure+". ";if(imported)FilterImports();next();return;}
     string target=solution.Suggested??ChooseTarget(solution);if(target==null){L("StatusLabel").Text="Identification stopped: "+named+" filename matches and "+solved+" plate-solved captures completed.";return;}
     Run(ct=>{FitsImage reference=items.Count>1?Assets.Analysis(sample,CapturePath(sample,imported),ct):null;var stars=reference!=null?Rotation.Detect(reference):null;foreach(var original in items){ct.ThrowIfCancellationRequested();Frame updated=original.Clone();try{if(original!=sample){FitsImage image=Assets.Analysis(original,CapturePath(original,imported),ct);if(image.Width!=reference.Width||image.Height!=reference.Height)throw new InvalidDataException("Different dimensions.");Rotation.Match(stars,Rotation.Detect(image),reference.Width,reference.Height,ct);}updated.Target=target;updated.TargetEvidence="Plate solved using "+solution.Solver+(original==sample?"":"; verified common stars with solved frame");updated.RA=solution.RA;updated.Dec=solution.Dec;updated.Notes=(updated.Notes??"")+updated.TargetEvidence+". ";StoreIdentification(original,updated,imported,ct);solved++;}catch(OperationCanceledException){throw;}catch(Exception e){unresolved++;if(imported)original.Notes=(original.Notes??"")+"Identification retained for review: "+e.Message+". ";}}return "";},done=>{if(imported)FilterImports();next();});
    });
   };next();
  }
